"use strict";(self.webpackChunkkeldev=self.webpackChunkkeldev||[]).push([[8928],{6980:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>i,toc:()=>l});var i=n(9290),a=n(4848),o=n(8453);const s={slug:"night-palace-again",title:"Night Palace Again",tags:["music","media","misc"],description:"A personal essay about Mount Eerie's 2024 album Night Palace",hide_reading_time:!0,date:new Date("2026-11-03T00:00:00.000Z")},r=void 0,h={authorsImageUrls:[]},l=[{value:"Dog, Deer, Air",id:"dog-deer-air",level:2},{value:"Turn",id:"turn",level:2},{value:"Night Palace, Again",id:"night-palace-again",level:2}];function d(e){const t={a:"a",blockquote:"blockquote",br:"br",code:"code",em:"em",h2:"h2",p:"p",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:["It's November. So as the trees release their canopy to the ground once again, and the leaves themselves traverse that lively gradient through ember and amber and down into mulch and dust, leaving barer limbs to gesture through chiller winds at greyer skies, I've been listening to ",(0,a.jsx)(t.em,{children:"Night Palace"})," again. It's kind of perfect for this."]}),"\n","\n",(0,a.jsx)(t.p,{children:"The trees in my backyard drop fewer and fewer leaves each day, and they gather in the grass like heaps of time in my own seasonal hourglass. Daylight's running out, more each day. Even so, I recently joined with all the neighbors I don't speak to in my rural wooded Virginia neighborhood in our (also unspoken) yearly agreement to count time a bit differently, to send the daylight on its way a little earlier in the evening. The only clock in my house that didn't change all on its own was the seven-segment display clock on the stove. I set it sometime vaguely in the early afternoon, to some other time vaguely in the early afternoon. I believe I fed the dog on time that day, so I guess I fed her an hour late. I'm not sure she noticed either way."}),"\n",(0,a.jsxs)(t.p,{children:["I don't think ",(0,a.jsx)(t.em,{children:"Night Palace"})," is deliberately set at a particular time of year, but I do find it resonates most strongly with the colder months. There is a sharper sense of ",(0,a.jsx)(t.em,{children:"inside"})," and ",(0,a.jsx)(t.em,{children:"outside"}),". There's often a harshness to the elements. It's a bit grey and damp, a bit blue. You might want a jacket."]}),"\n",(0,a.jsx)(t.h2,{id:"dog-deer-air",children:"Dog, Deer, Air"}),"\n",(0,a.jsx)(t.p,{children:"When I go out with the dog in midwinter we start in the front yard. I step from driveway gravel crunch to dead grass crunch. The sharpness of the winter air strikes the back of my nose and cuts a path for the smell of distant woodstove smoke to follow on the breeze. There's a heavy sort of silence that comes from the trees waiting, anticipating that next brush of smoky wind, as the land sleeps and the dog and I do our best not to wake it. It's not as heavy as the smothered silence of a landscape frozen under recent snowfall, but it's pretty close."}),"\n",(0,a.jsxs)(t.p,{children:["Eight tracks into ",(0,a.jsx)(t.em,{children:"Night Palace"}),", Elverum describes a ",(0,a.jsx)(t.a,{href:"https://genius.com/Mount-eerie-soft-air-lyrics",children:"(soft air)"})," that descends, and where in later tracks he might spend minutes speaking verse after verse about a particular experience, here his words give way to pure instrumental sound. The (soft air) blows into his lungs in a way that I cannot now describe again to you, because the nature of that air is not in words. Two years ago a commenter online called ",(0,a.jsx)(t.code,{children:"locustpupil"})," ",(0,a.jsx)(t.a,{href:"https://genius.com/Mount-eerie-soft-air-lyrics#:~:text=interesting%20air",children:"remarked"})," about the (soft air), \"interesting air, idk i'm not from anacortes so idk if the air [there] really does generate almost a minute's worth of fuzz tones\"."]}),"\n",(0,a.jsx)(t.p,{children:"When I go out with the dog in midwinter we start in the front yard. By the time we've gone around the side of the house and into the backyard I've lost the sharp clarity of the winter air to the blunt wet stench of combustion heat exhaust spilling from a downward-pointing elbow of PVC that juts out the back wall of the house. I can hear the hot gas hiss around the bend in the pipe, can see it slowly rise as the water condenses out of the other elements into little white clouds. Soon I will return to the furnace warmth and the incandescent lighting inside and I will look out the window at a cold grey midday as I shed my insulation and thaw out, but for now I am with the cold, am in it. The dog and I will walk further downhill toward the frosted leaf crunch of the woods and the smell will fade again."}),"\n",(0,a.jsxs)(t.p,{children:["Every time I hear that eighth track now I think about ",(0,a.jsx)(t.code,{children:"locustpupil"})," the commenter looking out their own window at the same fuzz tones that I'm hearing now and that Phil Elverum felt in his lungs. I think of them imagining, as I do, what it might be like to wander around Anacortes, Washington in the fuzzy soft air, where Phil Elverum does his living and thinking from."]}),"\n",(0,a.jsx)(t.p,{children:"When I go out with my dog at midnight, in midwinter, we stay in the warding motion light of the carport. She dives into the half-dark off the side of the house with a retractable leash lifeline back to me and I play lighthouse, scanning the horizon and tree line with my little flashlight. Some nights, deer have settled around the driveway and in the sudden light and sound of our emergence they leap from gravel crunch to earth thud and briefly clatter across the street to disappear among the trees. Other nights, I catch them wandering those distant woods and we just silently observe each other. Their blinking eyes reflect the searchlight of my carport vigil back at me while the dog sniffs out neighbor cats and other critters that like to hang around the shelter of the carport. I'm not sure she notices those distant watchers in the trees."}),"\n",(0,a.jsx)(t.p,{children:"Some nights the winter moon is so brilliant I find I don't need my own feeble light at all. On those nights I like to step off into the deep blue-grey cast of the front yard and look back at the warm orange glow peeking back at me from around drawn curtains and between closed blinds. In the moonlight I can see all the way into the neighboring fields beside me and down the long road, can easily scan the tree line behind me. The deer know this too, so I tend not to spot them out in the open on those nights. I imagine they spot me instead."}),"\n",(0,a.jsx)(t.h2,{id:"turn",children:"Turn"}),"\n",(0,a.jsx)(t.p,{children:'This week I will join with all the neighbors I don\'t speak to in my rural wooded Virginia neighborhood in our occasional agreement to decide, in bits and pieces, how our society feels about and represents itself. On the turn off the highway onto the road where I live there is a billboard captioned "Know Your Vote" with a few pictures. One is a pregnant person, hands on baby bump. There might be an ultrasound. One is an embracing pair of hands, one masculine and one feminine. You might see the edges of one suit and one white dress over flowers and a soft white background.'}),"\n",(0,a.jsxs)(t.p,{children:["Track 17 of ",(0,a.jsx)(t.em,{children:"Night Palace"})," is the blunt-titled Non-Metaphorical Decolonization. This section of the album takes what initially felt to me like an unexpected turn into candid thoughts about ideas like the absurdity of ownership, and how colonial history is violent, recent, and fundamentally tied to our present. Two years ago, with the release of this track as ",(0,a.jsx)(t.em,{children:"Night Palace"}),"'s final single, Phil Elverum ",(0,a.jsx)(t.a,{href:"https://pwelverumandsun.substack.com/p/night-palace-looms",children:"blogged"}),' online that "Here ... on the Pacific west edge of North America, where I do this living and thinking from, the shallow topsoil of the dominant history barely conceals what was here before, and the genocidal brutality that our current lives rest on. We know it and we don\'t talk about it." In this track, he talks about it.']}),"\n",(0,a.jsx)("div",{className:"lyrics",children:(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsxs)(t.p,{children:["Now we live in the wreckage of a colonizing force",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0whose racist poison still flows",(0,a.jsx)(t.br,{}),"\n","so scared of a moment of discomfort now",(0,a.jsx)(t.br,{}),"\n","we turn away from the obvious:",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0all we have is stolen and can't be owned"]}),"\n",(0,a.jsx)(t.p,{children:'\xa0\xa0\xa0\xa0This "America", the old idea, I want it to die.'}),"\n",(0,a.jsxs)(t.p,{children:["Non-metaphorical decolonization",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0beneath the one sky",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0Let this old world shatter",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0and transform"]}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.a,{href:"https://genius.com/Mount-eerie-non-metaphorical-decolonization-lyrics",children:(0,a.jsx)(t.em,{children:"17: Non-Metaphorical Decolonization"})})}),"\n"]})}),"\n",(0,a.jsxs)(t.p,{children:["I think it's the specific, direct verbiage that made this section of the album feel like an unexpected turn to me. It's the stripping away of metaphor for a moment. After this section, the last leg of ",(0,a.jsx)(t.em,{children:"Night Palace"})," continues on to consider what it is to exist in the context of history, to drown in the rush of current events, and to witness, to feel, interpret, and express within that context and that current. I don't think ",(0,a.jsx)(t.em,{children:"Night Palace"})," was deliberately conceived as a pointed album about these specific ideas. I wouldn't call it a concept album. But I do think Elverum found a handful of concepts that resonate most strongly with the whole work, and with each other, and managed to convey them clearly within the work itself."]}),"\n",(0,a.jsx)("div",{className:"lyrics",children:(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsxs)(t.p,{children:["Nothing's mine, I draw a line",(0,a.jsx)(t.br,{}),"\n",'a wind blows and says "Nice try"']}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.a,{href:"https://genius.com/Mount-eerie-co-owner-of-trees-lyrics",children:(0,a.jsx)(t.em,{children:"19: Co-Owner of Trees"})})}),"\n"]})}),"\n",(0,a.jsx)("div",{className:"lyrics",children:(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsxs)(t.p,{children:["It was only one night in a tent \xa0\xa0\xa0\xa0\xa0 alone on a peak",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0so quiet I might have actually been nowhere"]}),"\n",(0,a.jsxs)(t.p,{children:["I never meant to pretend there's another world",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0apart from the one we're in"]}),"\n",(0,a.jsxs)(t.p,{children:["but I was briefly adrift in a night sky",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0before being re-immersed in this endless et cetera"]}),"\n",(0,a.jsxs)(t.p,{children:["now I remember the news and the names",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0and who I am \xa0\xa0\xa0\xa0\xa0 and where on the map I went"]}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.a,{href:"https://genius.com/Mount-eerie-stone-woman-gives-birth-to-a-child-at-night-lyrics",children:(0,a.jsx)(t.em,{children:"24: Stone Woman Gives Birth To A Child At Night"})})}),"\n"]})}),"\n",(0,a.jsxs)(t.p,{children:["On the Wikipedia page for ",(0,a.jsx)(t.a,{href:"https://en.wikipedia.org/wiki/2026_Virginia_Question_2",children:"2026 Virginia Question 2"}),', beneath an exact description of a proposed constitutional wording change, there is a list of endorsements. The proposition would change an exclusionary definition of valid marriage as "only a union between one man and one woman" to a deliberately more inclusive limitation that the Commonwealth "shall not deny the issuance of a marriage license to two adult persons seeking a lawful marriage on the basis of sex, gender, or race of such persons". The original same-sex marriage ban is something Virginians voted for 20 years ago. The ban is currently unenforceable, because of a Supreme Court ruling 11 years ago. That ruling came about 40 years after ',(0,a.jsx)(t.em,{children:"Roe v. Wade"})," rendered many state-level abortion bans similarly unenforceable, for a time."]}),"\n",(0,a.jsxs)(t.p,{children:["Today, 0 years ago, the endorsements for 2026 Virginia Question 2 ",(0,a.jsx)(t.a,{href:"https://ballotpedia.org/Virginia_Question_2,_Remove_Constitutional_Same-Sex_Marriage_Ban_Amendment_(2026)#Support:~:text=Political%20Parties",children:"split"})," along ",(0,a.jsx)(t.a,{href:"https://ballotpedia.org/Virginia_Question_2,_Remove_Constitutional_Same-Sex_Marriage_Ban_Amendment_(2026)#Political_Parties:~:text=R%29-,Political%20Parties",children:"party lines"}),". Conveniently for the voting public, endorsements split towards the same answers for all three of the ",(0,a.jsx)(t.a,{href:"https://en.wikipedia.org/wiki/2026_Virginia_elections#Abortion_rights_amendment",children:"2026 Virginia Questions"}),". ",(0,a.jsx)(t.em,{children:"D"})," is ",(0,a.jsx)(t.em,{children:"yes and yes and yes"}),", and ",(0,a.jsx)(t.em,{children:"R"})," is ",(0,a.jsx)(t.em,{children:"no and no and no"}),". On the turn off the highway onto the road where I live there is one singular billboard about no question in particular. With its images it gestures at institution and values and ideology. With its caption it tells me to vote, to know. And then I turn away, off the highway, and come home. I don't actually remember if the billboard has a third picture for the third Question. I don't actually know if each of the neighbors I don't speak to in my rural wooded Virginia neighborhood will agree to vote yes or no, or yes or no, or yes or no, for the 2026 Virginia Questions. But I do remember the signs they stood up in their yard two years ago: political slogans and calls to action, triumphant images of a bloody-eared fist pump, garish flags and mugshots. Many stayed up for a long time, over a year. More recently, some have come down and have not been replaced. The billboard is new."]}),"\n",(0,a.jsx)(t.p,{children:"Track 18 is called November Rain. It is Elverum's perspective as a year-round resident of a place that's seen as a vacation town, and his relationship to the seasonally-present owners of the neighboring houses, and to ownership itself. It is driving acoustic guitar strumming under bright and clear singing, and then it all rumbles and tears a bit. Eventually it shimmers, then drowns in cymbals until a last note spills out. It's all verses, no chorus, and I keep thinking about the last few:"}),"\n",(0,a.jsx)("div",{className:"lyrics",children:(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsxs)(t.p,{children:["\xa0\xa0\xa0\xa0All these absentee owners miss",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0the huge embrace, the pressing kiss",(0,a.jsx)(t.br,{}),"\n","of this specific November rain in the long darkness",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0but that's OK",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0I'll drink all the rain while I trespass"]}),"\n",(0,a.jsxs)(t.p,{children:["\xa0\xa0\xa0\xa0they keep the outside light on though",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0\xa0\xa0\xa0\xa0I guess to let everyone else know",(0,a.jsx)(t.br,{}),"\n",'"keep away, this patch of night sky I also claim as mine"']}),"\n",(0,a.jsxs)(t.p,{children:["but don't they realize",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0all our stolen wealth is built on screaming bones?"]}),"\n",(0,a.jsxs)(t.p,{children:["\xa0\xa0\xa0\xa0In their lights that dot the hillside",(0,a.jsx)(t.br,{}),"\n","\xa0\xa0\xa0\xa0I see blinking eyes"]}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.a,{href:"https://genius.com/Mount-eerie-november-rain-lyrics",children:(0,a.jsx)(t.em,{children:"18: November Rain"})})}),"\n"]})}),"\n",(0,a.jsxs)(t.p,{children:["In notes included with the vinyl release of ",(0,a.jsx)(t.em,{children:"Night Palace"}),", Elverum shares his bitterness for these owners: \"The school teachers and service workers wince and limp along while the land owners with too much laugh behind their locked gates for a couple weeks a year. When they leave, there are security cameras deep in the woods and threatening signs everywhere. These people's lives pass in a deep desperate sense of lack.\" In the next track, Elverum prods these boundaries, walking property lines, hiding from neighbors. He speaks a spell against their private property signs. To the best of my knowledge, the neighbors I don't speak to in my rural wooded Virginia neighborhood do not live year-round in the issue of same-sex marriage, the issue of 2026 Virginia Question 2. This week, we will all vote about it. I will speak a spell."]}),"\n",(0,a.jsx)(t.h2,{id:"night-palace-again",children:"Night Palace, Again"}),"\n",(0,a.jsxs)(t.p,{children:["It's November. So as I join the neighbors with whom I share this flaming globe, as we blink and spot each other across the tree line, draw lines in the wind, prioritize joy, feel the soft air, choose to see this and not that, immerse ourselves in this endless et cetera, I've been listening to ",(0,a.jsx)(t.em,{children:"Night Palace"})," again. It's kind of perfect for this."]}),"\n",(0,a.jsx)(t.p,{children:"Thanks for reading."}),"\n",(0,a.jsx)("br",{}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.em,{children:"Notes:"}),(0,a.jsx)(t.br,{}),"\n",(0,a.jsxs)(t.em,{children:["I previously recommended this album ",(0,a.jsx)(t.a,{href:"https://keldev.net/blog/albums-i-enjoyed-in-2025#night-palace-mount-eerie",children:"elsewhere"}),", though I do hope I've done a better job of it here."]}),(0,a.jsx)(t.br,{}),"\n",(0,a.jsx)(t.em,{children:"For lyrical quotes I tried to use capitalization, line breaks, and some odd spacing that reflects how they're presented in the vinyl release. Didn't get it exactly though. It's a lot of extra space."})]})]})}function c(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>r});var i=n(6540);const a={},o=i.createContext(a);function s(e){const t=i.useContext(o);return i.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),i.createElement(o.Provider,{value:t},e.children)}},9290:e=>{e.exports=JSON.parse('{"permalink":"/blog/night-palace-again","source":"@site/blog/2026-11-03-night-palace-again.mdx","title":"Night Palace Again","description":"A personal essay about Mount Eerie\'s 2024 album Night Palace","date":"2026-11-03T00:00:00.000Z","tags":[{"inline":false,"label":"Music","permalink":"/blog/tags/music","description":"Posts about music."},{"inline":false,"label":"Media","permalink":"/blog/tags/media","description":"Posts about media (music, games, books, etc.)."},{"inline":false,"label":"Misc.","permalink":"/blog/tags/misc","description":"Miscellanious posts that may not fit into many (or any) other categories."}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"night-palace-again","title":"Night Palace Again","tags":["music","media","misc"],"description":"A personal essay about Mount Eerie\'s 2024 album Night Palace","hide_reading_time":true,"date":"2026-11-03T00:00:00.000Z"},"unlisted":false,"nextItem":{"title":"Albums I Enjoyed in 2025","permalink":"/blog/albums-i-enjoyed-in-2025"}}')}}]);